<style>body{margin:0;background:transparent;color:#b9d5e9;font:13px Segoe UI,Arial,sans-serif}table{width:100%;border-collapse:collapse}th,td{padding:8px;border-bottom:1px solid #10293b;text-align:left}th{color:#7898b0;font-size:11px}.ok{color:#23e769}.wait{color:#469cff}.warn{color:#ffad16}.bad{color:#ff5545}.metric{display:flex;justify-content:space-between;padding:9px;border-bottom:1px solid #10293b}.bar{height:7px;background:#102334;border-radius:10px;overflow:hidden;margin-top:5px}.bar span{display:block;height:100%;background:#00d9ff}.card{border:1px solid #12334a;border-radius:8px;padding:12px;margin-bottom:8px;background:#04101c}</style>
